<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';
import Modal from '../components/Modal.vue';import StoreManagerEdit from './StoreManagerEdit.vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab}>();const work=useWorkspace();const data=ref<any>(null),query=ref(''),error=ref(''),loading=ref(false),showResults=ref(false),storeQuery=ref(''),editing=ref<any>(null),discard=ref(false);
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api('store-managers');}catch(e){data.value=null;error.value=(e as Error).message;}finally{loading.value=false;}}
const rows=computed(()=>{if(!query.value.trim())return [];const map=new Map<string,any>();for(const u of data.value?.users || [])map.set(u.id,{...u,eligible:true});for(const a of data.value?.assignments || [])if(!map.has(a.user_id))map.set(a.user_id,{...a.user,id:a.user_id,eligible:false});return [...map.values()].filter(u=>[u.full_name,u.email,u.employee_code,u.job_title].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>(a.employee_code||a.full_name||'').localeCompare(b.employee_code||b.full_name||''));});
const overview=computed(()=>(data.value?.stores||[]).map((s:any)=>({...s,managers:(data.value?.assignments||[]).filter((a:any)=>a.store_id===s.id).map((a:any)=>a.user||{id:a.user_id,full_name:'人員資料缺失'})})).filter((s:any)=>s.managers.length&&[s.store_code,s.store_name,...s.managers.map((u:any)=>[u.full_name,u.employee_code].join(' '))].join(' ').toLowerCase().includes(storeQuery.value.trim().toLowerCase())).sort((a:any,b:any)=>a.store_code.localeCompare(b.store_code,'zh-Hant',{numeric:true})||a.id.localeCompare(b.id)));
function edit(u:any){props.tab.recordId=u.id;editing.value=u;showResults.value=false;query.value='';}
function leaveSearch(event:FocusEvent){if(!(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node|null))showResults.value=false;}
function close(){if(props.tab.busy)return;if(props.tab.dirty){discard.value=true;return;}editing.value=null;}
function abandon(){props.tab.dirty=false;discard.value=false;editing.value=null;}

onMounted(load);watch(()=>work.active,id=>{if(id===props.tab.id)load();});
</script>
<template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 店長指派</p><h1>店長指派</h1><p class="muted">搜尋人員後選擇管理門市，或查看各門市目前指派的店長。</p></div><button :disabled="loading" @click="load">重新整理</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="person-picker" @focusout="leaveSearch" @keydown.esc.stop.prevent="showResults=false"><label class="manager-search">搜尋店長<input v-model="query" :disabled="loading||!data" placeholder="輸入姓名、員編或電子郵件" autocomplete="off" @input="showResults=true" @focus="showResults=true"></label><div v-if="showResults&&query.trim()&&data" class="person-results" role="region" aria-label="人員搜尋結果"><button v-for="u in rows" :key="u.id" class="person-option" @click="edit(u)"><strong>{{u.full_name||u.email||'未命名'}}</strong><span>{{u.employee_code||'無員編'}} · {{u.job_title||'未提供職稱'}}</span><small v-if="!u.eligible">僅可解除既有指派</small></button><p v-if="!rows.length" role="status">沒有符合搜尋的人員</p></div></div><section class="assignment-overview" aria-label="門市指派總覽"><h2>門市指派總覽</h2><label class="manager-search">搜尋已指派門市<input v-model="storeQuery" placeholder="門市代號、名稱、店長姓名或員編"></label><p v-if="loading" role="status">載入門市指派…</p><template v-else-if="data"><p class="muted">{{overview.length}} 間已指派門市 · 依門市代號升冪排列</p><div class="module-table overview-table"><table><thead><tr><th aria-sort="ascending">門市代號 ↑</th><th>門市名稱</th><th>目前指派店長</th></tr></thead><tbody><tr v-for="s in overview" :key="s.id"><td>{{s.store_code}}</td><td>{{s.store_name}}<span v-if="!s.is_active">（停用）</span></td><td><ul><li v-for="u in s.managers" :key="u.id"><button class="manager-link" @click="edit(u)">{{u.full_name||'未命名'}}<span v-if="u.employee_code"> · {{u.employee_code}}</span></button></li></ul></td></tr><tr v-if="!overview.length"><td colspan="3">{{storeQuery?'沒有符合搜尋的已指派門市':'尚無已指派店長的門市'}}</td></tr></tbody></table></div></template></section><Modal v-if="editing" :title="'選擇管理門市 · '+(editing.full_name||editing.employee_code||'未命名')" :busy="tab.busy" @cancel="close"><StoreManagerEdit :tab="tab" embedded @saved="load" @close="close" /></Modal><Modal v-if="discard" title="放棄尚未儲存的指派？" @cancel="discard=false"><p>目前勾選尚未儲存，關閉會放棄這次修改。</p><div class="dialog-actions"><button @click="discard=false">繼續編輯</button><button class="danger" @click="abandon">放棄修改並關閉</button></div></Modal></template>
<style scoped>.person-picker{position:relative;max-width:480px;margin-bottom:32px}.person-results{position:absolute;inset:100% 0 auto;z-index:5;max-height:300px;overflow:auto;background:var(--surface);border:1px solid var(--line);box-shadow:0 6px 16px #0002}.person-results p{padding:12px}.person-option{display:flex;flex-direction:column;align-items:flex-start;gap:4px;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:12px 16px;overflow-wrap:anywhere}.person-option span,.person-option small{color:var(--muted)}.person-option:hover,.person-option:focus-visible{background:var(--soft)}.assignment-overview h2{font-size:18px;margin-bottom:20px}.manager-link{text-align:left}.module-table li+li{margin-top:8px}.manager-search{display:grid;gap:8px;max-width:480px}.module-table ul{margin:0;padding-left:18px}@media(max-width:600px){.overview-table table{min-width:0;table-layout:fixed}.overview-table th,.overview-table td{white-space:normal;overflow-wrap:anywhere;padding:10px 6px}.overview-table th:first-child{width:23%}.overview-table th:nth-child(2){width:29%}.overview-table ul{padding-left:0;list-style:none}.manager-link{max-width:100%;padding:8px;white-space:normal;overflow-wrap:anywhere}}</style>
